#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_deleteNode_node_with_only_left_child(void) {
    // Build a tree where the node to delete has only a left child.
    // We will delete the root (key 10), which has left child 5 and no right child.
    // This satisfies: root != NULL, key == root->key, root->left != NULL, root->right == NULL.
    int values[] = {10, 5};
    struct node* root = helper_build_tree(values, 2);

    // Verify tree contains the key before deletion
    helper_assert_tree_contains(root, 10);
    helper_assert_tree_contains(root, 5);

    // Capture inorder before deletion for verification
    helper_assert_tree_inorder(root, "5 10 ");

    // Delete node with key 10 (root)
    struct node* new_root = deleteNode(root, 10);

    // Assertions:
    // 1. The new root should not be NULL (tree still has node 5)
    TEST_ASSERT_NOT_NULL(new_root);
    // 2. The new root should be the left child (key 5)
    TEST_ASSERT_EQUAL_INT(5, new_root->key);
    // 3. The new root should have no children (since original left child of 10 had no children)
    TEST_ASSERT_NULL(new_root->left);
    TEST_ASSERT_NULL(new_root->right);
    // 4. The tree should no longer contain key 10
    helper_assert_tree_not_contains(new_root, 10);
    // 5. The tree should still contain key 5
    helper_assert_tree_contains(new_root, 5);
    // 6. Inorder traversal should be just "5 "
    helper_assert_tree_inorder(new_root, "5 ");

    // Cleanup
    helper_free_tree(new_root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_deleteNode_node_with_only_left_child);
    return UNITY_END();
}

